import pandas as pd
import numpy as np
import json
import sys

def to_float(x):
    return float(x) if pd.notna(x) else None

def main():
    path = sys.argv[1]
    df = pd.read_csv(path)

    facts = []

    # ---- TOTALS ----
    rev_tw_sum = df['Revenue_TW'].sum(skipna=True)
    rev_lw_sum = df['Revenue_LW'].sum(skipna=True)
    rev_ly_sum = df['Revenue_LY'].sum(skipna=True)
    units_tw_sum = df['Units_TW'].sum(skipna=True)
    units_lw_sum = df['Units_LW'].sum(skipna=True)
    orders_tw_sum = df['Orders_TW'].sum(skipna=True)
    orders_lw_sum = df['Orders_LW'].sum(skipna=True)

    facts.append({
        "entity": "TOTAL", "metric": "revenue", "period": "TW",
        "value": round(float(rev_tw_sum), 2),
        "formula": "sum(Revenue_TW)"
    })
    facts.append({
        "entity": "TOTAL", "metric": "revenue", "period": "LW",
        "value": round(float(rev_lw_sum), 2),
        "formula": "sum(Revenue_LW)"
    })
    if df['Revenue_LY'].notna().any():
        facts.append({
            "entity": "TOTAL", "metric": "revenue", "period": "LY",
            "value": round(float(rev_ly_sum), 2),
            "formula": "sum(Revenue_LY)"
        })

    if rev_lw_sum and not np.isnan(rev_lw_sum) and rev_lw_sum != 0:
        wow_total = (rev_tw_sum - rev_lw_sum) / rev_lw_sum * 100
        facts.append({
            "entity": "TOTAL", "metric": "revenue", "period": "WoW",
            "value": round(float(wow_total), 1),
            "formula": "(sum(Revenue_TW) - sum(Revenue_LW)) / sum(Revenue_LW) * 100"
        })

    if rev_ly_sum and not np.isnan(rev_ly_sum) and rev_ly_sum != 0:
        yoy_total = (rev_tw_sum - rev_ly_sum) / rev_ly_sum * 100
        facts.append({
            "entity": "TOTAL", "metric": "revenue", "period": "YoY",
            "value": round(float(yoy_total), 1),
            "formula": "(sum(Revenue_TW) - sum(Revenue_LY)) / sum(Revenue_LY) * 100"
        })

    facts.append({
        "entity": "TOTAL", "metric": "units", "period": "TW",
        "value": round(float(units_tw_sum), 2),
        "formula": "sum(Units_TW)"
    })
    facts.append({
        "entity": "TOTAL", "metric": "units", "period": "LW",
        "value": round(float(units_lw_sum), 2),
        "formula": "sum(Units_LW)"
    })
    if units_lw_sum != 0:
        units_wow = (units_tw_sum - units_lw_sum) / units_lw_sum * 100
        facts.append({
            "entity": "TOTAL", "metric": "units", "period": "WoW",
            "value": round(float(units_wow), 1),
            "formula": "(sum(Units_TW) - sum(Units_LW)) / sum(Units_LW) * 100"
        })

    facts.append({
        "entity": "TOTAL", "metric": "orders", "period": "TW",
        "value": round(float(orders_tw_sum), 2),
        "formula": "sum(Orders_TW)"
    })
    facts.append({
        "entity": "TOTAL", "metric": "orders", "period": "LW",
        "value": round(float(orders_lw_sum), 2),
        "formula": "sum(Orders_LW)"
    })
    if orders_lw_sum != 0:
        orders_wow = (orders_tw_sum - orders_lw_sum) / orders_lw_sum * 100
        facts.append({
            "entity": "TOTAL", "metric": "orders", "period": "WoW",
            "value": round(float(orders_wow), 1),
            "formula": "(sum(Orders_TW) - sum(Orders_LW)) / sum(Orders_LW) * 100"
        })

    # ---- TOP ENTITIES BY RANK ----
    if 'Rank' in df.columns:
        top_df = df.dropna(subset=['Rank']).sort_values('Rank').head(3)
        for _, row in top_df.iterrows():
            facts.append({
                "entity": row['Entity'], "metric": "revenue", "period": "TW",
                "value": round(float(row['Revenue_TW']), 2) if pd.notna(row['Revenue_TW']) else None,
                "formula": "Revenue_TW"
            })
            if pd.notna(row.get('Share_Pct')):
                facts.append({
                    "entity": row['Entity'], "metric": "share", "period": "TW",
                    "value": round(float(row['Share_Pct']), 1),
                    "formula": "Share_Pct"
                })
            if pd.notna(row.get('Rank')):
                facts.append({
                    "entity": row['Entity'], "metric": "rank", "period": "TW",
                    "value": round(float(row['Rank']), 1),
                    "formula": "Rank"
                })

    # ---- TOP / BOTTOM WoW MOVERS ----
    wow_df = df.dropna(subset=['WoW_Pct']).sort_values('WoW_Pct', ascending=False)
    if not wow_df.empty:
        top_gain = wow_df.iloc[0]
        facts.append({
            "entity": top_gain['Entity'], "metric": "revenue", "period": "WoW",
            "value": round(float(top_gain['WoW_Pct']), 1),
            "formula": "WoW_Pct (top gainer)"
        })
        top_loss = wow_df.iloc[-1]
        if top_loss['Entity'] != top_gain['Entity']:
            facts.append({
                "entity": top_loss['Entity'], "metric": "revenue", "period": "WoW",
                "value": round(float(top_loss['WoW_Pct']), 1),
                "formula": "WoW_Pct (top decliner)"
            })

    # ---- TOP / BOTTOM YoY MOVERS ----
    yoy_df = df.dropna(subset=['YoY_Pct']).sort_values('YoY_Pct', ascending=False)
    if not yoy_df.empty:
        top_gain_y = yoy_df.iloc[0]
        facts.append({
            "entity": top_gain_y['Entity'], "metric": "revenue", "period": "YoY",
            "value": round(float(top_gain_y['YoY_Pct']), 1),
            "formula": "YoY_Pct (top gainer)"
        })
        top_loss_y = yoy_df.iloc[-1]
        if top_loss_y['Entity'] != top_gain_y['Entity']:
            facts.append({
                "entity": top_loss_y['Entity'], "metric": "revenue", "period": "YoY",
                "value": round(float(top_loss_y['YoY_Pct']), 1),
                "formula": "YoY_Pct (top decliner)"
            })

    # ---- ENTITY WITH LOWEST REVENUE_TW ----
    rev_df = df.dropna(subset=['Revenue_TW']).sort_values('Revenue_TW')
    if not rev_df.empty:
        lowest = rev_df.iloc[0]
        facts.append({
            "entity": lowest['Entity'], "metric": "revenue", "period": "TW",
            "value": round(float(lowest['Revenue_TW']), 2),
            "formula": "Revenue_TW (lowest among entities)"
        })

    # Trim to 25 facts max
    facts = facts[:25]

    # Clean None values, ensure python floats
    clean_facts = []
    for f in facts:
        if f["value"] is None:
            continue
        clean_facts.append({
            "entity": f["entity"],
            "metric": f["metric"],
            "period": f["period"],
            "value": float(f["value"]),
            "formula": f["formula"]
        })

    print(json.dumps(clean_facts))

if __name__ == "__main__":
    main()
